function load(){let raw=localStorage.getItem(KEY);if(!raw){let s=seed();localStorage.setItem(KEY,JSON.stringify(s));return s}try{let s=JSON.parse(raw);if(s.version!==5){let n=seed();localStorage.setItem(KEY,JSON.stringify(n));return n}return s}catch{let s=seed();localStorage.setItem(KEY,JSON.stringify(s));return s}}
let S=load();
function save(){localStorage.setItem(KEY,JSON.stringify(S))}
function session(){try{return JSON.parse(localStorage.getItem(SESSION)||'null')}catch{return null}}
function currentUser(){let x=session();return x?S.users.find(u=>u.id===x.userId&&u.active):null}
function currentMember(){let u=currentUser();return u?.memberId?S.members.find(m=>m.id===u.memberId):null}
function log(action,entity,detail=''){let u=currentUser();S.audit.unshift({id:uid('AU'),time:iso(),userId:u?.id||'PUBLIC',action,entity,detail});S.audit=S.audit.slice(0,400);save()}
function isAdmin(u=currentUser()){return !!u&&u.role==='admin'}
function canManageDepartment(depId,u=currentUser()){if(!u)return false;if(u.role==='admin'||u.role==='president')return true;let d=S.departments.find(x=>x.id===depId);if(!d)return false;if(u.role===d.leadRole)return true;let m=u.memberId&&S.members.find(x=>x.id===u.memberId);return !!m?.departmentIds?.includes(depId)}
function requireAuth(){if(!currentUser()){location.href='login.html?next='+encodeURIComponent(location.pathname.split('/').pop()+location.hash);return false}return true}
function activeMeeting(){return S.meetings.find(m=>m.status==='open')||S.meetings.find(m=>new Date(m.date)>=new Date().setHours(0,0,0,0))||S.meetings[0]}
function memberName(id){return S.members.find(m=>m.id===id)?.fullName||'—'}
function powerName(id){return S.powerTeams.find(p=>p.id===id)?.name||'—'}
function userName(id){let u=S.users.find(x=>x.id===id);return u?.memberId?memberName(u.memberId):(u?.username||id||'—')}
function toast(msg,type=''){let st=q('.toast-stack');if(!st){st=document.createElement('div');st.className='toast-stack';document.body.append(st)}let el=document.createElement('div');el.className='toast';if(type==='success')el.style.borderLeftColor='#18794e';el.innerHTML=`<strong>${type==='success'?'Thành công':'Thông báo'}</strong>${esc(msg)}`;st.append(el);setTimeout(()=>el.remove(),3500)}
window.toast=toast;
function openModal(title,html){let b=q('#modal'); if(!b){b=document.createElement('div');b.id='modal';b.className='modal-backdrop';b.innerHTML='<div class="modal"><button class="modal-close" onclick="closeModal()">Đóng</button><h2 id="modalTitle"></h2><div id="modalBody"></div></div>';document.body.append(b)}q('#modalTitle',b).textContent=title;q('#modalBody',b).innerHTML=html;b.classList.remove('hide')}
window.closeModal=()=>q('#modal')?.classList.add('hide');
function fileMeta(input,max=10){return [...(input?.files||[])].slice(0,max).map(f=>({name:f.name,size:f.size,type:f.type,lastModified:f.lastModified}))}
function openFileDB(){return new Promise((resolve,reject)=>{let req=indexedDB.open('c11_erp_files_v5',1);req.onupgradeneeded=()=>{let db=req.result;if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function persistInputFiles(input,max=10,group='other'){let fs=[...(input?.files||[])].slice(0,max),out=[];if(!fs.length)return out;try{let db=await openFileDB();for(let f of fs){let key=uid('FILE');await new Promise((res,rej)=>{let tx=db.transaction('files','readwrite');tx.objectStore('files').put({key,blob:f,name:f.name,type:f.type,size:f.size,group,createdAt:iso()});tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});out.push({storageKey:key,name:f.name,size:f.size,type:f.type,typeGroup:group,lastModified:f.lastModified})}db.close();return out}catch(e){console.warn('IndexedDB file fallback',e);return fs.map(f=>({name:f.name,size:f.size,type:f.type,typeGroup:group,lastModified:f.lastModified}))}}
window.downloadStoredFile=async key=>{try{let db=await openFileDB();let obj=await new Promise((res,rej)=>{let tx=db.transaction('files','readonly');let r=tx.objectStore('files').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});db.close();if(!obj)return toast('Không tìm thấy file trong bộ nhớ trình duyệt');let url=URL.createObjectURL(obj.blob),a=document.createElement('a');a.href=url;a.download=obj.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast('Không thể mở file đã lưu')}}

function validPassword(p){return /[A-Z]/.test(p)&&/[a-z]/.test(p)&&/\d/.test(p)&&p.length>=8}
function generatePassword(){const A='ABCDEFGHJKLMNPQRSTUVWXYZ',a='abcdefghijkmnopqrstuvwxyz',n='23456789';let p=A[Math.floor(Math.random()*A.length)]+a[Math.floor(Math.random()*a.length)]+n[Math.floor(Math.random()*n.length)];let all=A+a+n;while(p.length<10)p+=all[Math.floor(Math.random()*all.length)];return p.split('').sort(()=>Math.random()-.5).join('')}
function queueMail(to,subject,body){S.mailOutbox.unshift({id:uid('MAIL'),to,subject,body,createdAt:iso(),status:'queued'});save()}
function updateMeetingText(){let m=activeMeeting();qa('[data-meeting-name]').forEach(e=>e.textContent=m.name);qa('[data-meeting-meta]').forEach(e=>e.textContent=`${fmtDate(m.date)} • ${m.time} • ${m.location}`)}
function bindAdminLinks(){qa('.side-link[data-section]').forEach(a=>a.onclick=e=>{e.preventDefault();showAdminSection(a.dataset.section)})}
function statusChip(v){const map={active:['green','Đang hoạt động'],inactive:['gray','Không hoạt động'],pending:['gold','Chờ duyệt'],approved:['green','Đã duyệt'],confirmed:['green','Đã xác nhận'],open:['blue','Đang xử lý'],success:['green','Thành công'],scheduled:['blue','Đã lên lịch'],contacted:['blue','Đã liên hệ'],attended:['green','Đã tham dự'],planning:['gold','Đang chuẩn bị']};let x=map[v]||['gray',v||'—'];return `<span class="chip ${x[0]}">${esc(x[1])}</span>`}
function renderHome(){
 const active=S.members.filter(m=>m.status==='active'); let ops=S.opportunities; let m=activeMeeting();
 q('#homeMemberCount')&&(q('#homeMemberCount').textContent=active.length);q('#homeOppCount')&&(q('#homeOppCount').textContent=ops.length);q('#homeOppValue')&&(q('#homeOppValue').textContent=money(ops.reduce((a,b)=>a+b.value,0)).replace(' ₫',''));
 q('#nextMeetingName')&&(q('#nextMeetingName').textContent=m.name);q('#nextMeetingMeta')&&(q('#nextMeetingMeta').textContent=`${fmtDate(m.date)} • ${m.time} • ${m.location}`);
 let leaders=S.departments.slice(0,4).map(d=>{let mem=S.members.find(m=>m.departmentIds?.includes(d.id));return `<article class="card member-card"><div class="member-top"><div class="member-avatar">${esc(mem?.fullName?.split(' ').slice(-1)[0]?.[0]||'C')}</div><div><h3>${esc(mem?.fullName||'Đang cập nhật')}</h3><small>${esc(d.name)}</small></div></div><p>${esc(mem?.company||d.scope)}</p></article>`}).join('');q('#publicLeaders')&&(q('#publicLeaders').innerHTML=leaders);
 q('#publicPowerTeams')&&(q('#publicPowerTeams').innerHTML=S.powerTeams.slice(0,4).map(p=>`<article class="card power-card"><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><span class="chip red">${S.members.filter(m=>m.powerTeamId===p.id&&m.status==='active').length} hội viên</span></article>`).join(''));
 q('#publicDirectory')&&(q('#publicDirectory').innerHTML=active.slice(0,6).map(m=>memberCard(m)).join(''));
}
function memberCard(m){return `<article class="card member-card"><div class="member-top"><div class="member-avatar">${esc(m.fullName.split(' ').slice(-1)[0][0])}</div><div><h3>${esc(m.fullName)}</h3><small>${esc(m.industry)}</small></div></div><p><b>${esc(m.company)}</b><br>${esc(m.products)}</p><div class="member-meta"><span class="chip red">${esc(powerName(m.powerTeamId))}</span></div></article>`}
function renderPublicMembersPage(){let term=(q('#publicMemberSearch')?.value||'').toLowerCase();let pt=q('#publicPowerFilter')?.value||'';let list=S.members.filter(m=>m.status==='active'&&(!pt||m.powerTeamId===pt)&&(!term||[m.fullName,m.company,m.industry,m.products].join(' ').toLowerCase().includes(term)));q('#membersPublicGrid')&&(q('#membersPublicGrid').innerHTML=list.map(memberCard).join('')||'<div class="empty">Không có kết quả</div>');q('#membersPublicLeaders')&&(q('#membersPublicLeaders').innerHTML=S.departments.slice(0,9).map(d=>{let m=S.members.find(x=>x.departmentIds?.includes(d.id));return `<article class="card"><div class="eyebrow">${esc(d.name)}</div><h3>${esc(m?.fullName||'Đang cập nhật')}</h3><p>${esc(m?.company||d.scope)}</p></article>`}).join(''));let sel=q('#publicPowerFilter');if(sel&&sel.options.length===1)S.powerTeams.forEach(p=>sel.add(new Option(p.name,p.id)))}
window.renderPublicMembersPage=renderPublicMembersPage;
function renderPowerTeams(){let el=q('#powerTeamPublic');if(el)el.innerHTML=S.powerTeams.map(p=>`<article class="card power-card"><div class="eyebrow">Power Team</div><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><div class="member-meta">${S.members.filter(m=>m.powerTeamId===p.id&&m.status==='active').map(m=>`<span class="chip red">${esc(m.fullName)}</span>`).join('')||'<span class="chip gray">Chưa có hội viên</span>'}</div></article>`).join('')}
function renderMeetingPage(){let m=activeMeeting();q('#meetingDate')&&(q('#meetingDate').textContent=fmtDate(m.date));q('#meetingTime')&&(q('#meetingTime').textContent=m.time);q('#meetingLocation')&&(q('#meetingLocation').textContent=m.location);let at=S.attendance.filter(a=>a.meetingId===m.id);q('#meetingAttendance')&&(q('#meetingAttendance').textContent=at.length)}
function fillMemberSelect(el,includeGuests=false){if(!el)return;el.innerHTML='<option value="">-- Chọn --</option>'+S.members.filter(m=>m.status==='active').map(m=>`<option value="M:${m.id}">${esc(m.fullName)} • ${esc(m.industry)}</option>`).join('')+(includeGuests?S.guests.filter(g=>['attended','contacted'].includes(g.status)).map(g=>`<option value="G:${g.id}">${esc(g.fullName)} • Khách mời</option>`).join(''):'')}
function renderCheckin(){let t=q('#checkinType');if(t)checkinTypeChanged();let inv=q('#inviterId');if(inv){inv.innerHTML='<option value="">Không có / không nhớ</option>'+S.members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}">${esc(m.fullName)}</option>`).join('')}}
window.checkinTypeChanged=()=>{let t=q('#checkinType')?.value;let memberBox=q('#memberCheckinBox'),guestBox=q('#guestCheckinBox');if(memberBox)memberBox.classList.toggle('hide',t!=='chapter11');if(guestBox)guestBox.classList.toggle('hide',t==='chapter11');if(t==='chapter11'){let sel=q('#checkinMemberId');if(sel)sel.innerHTML='<option value="">-- Chọn hội viên --</option>'+S.members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}">${esc(m.fullName)} • ${esc(m.company)}</option>`).join('')}};
window.submitCheckin=e=>{e.preventDefault();let m=activeMeeting(),type=q('#checkinType').value, rec;if(type==='chapter11'){let id=q('#checkinMemberId').value,mem=S.members.find(x=>x.id===id);if(!mem)return toast('Vui lòng chọn hội viên');rec={personType:'member',personId:mem.id,fullName:mem.fullName,phone:mem.phone,role:'Hội viên Chapter 11',chapter:'11',company:mem.company,inviterId:null}}else{let name=normalizeName(q('#guestName')?.value),phone=q('#guestPhone')?.value.trim();if(!name||!phone)return toast('Vui lòng nhập họ tên và số điện thoại');rec={personType:'guest',personId:'',fullName:name,phone,role:q('#guestRole')?.value||'Khách mời',chapter:q('#guestChapter')?.value||'Khách',company:q('#guestCompany')?.value||'',inviterId:q('#inviterId')?.value||null}}let dup=S.attendance.find(a=>a.meetingId===m.id&&((rec.personId&&a.personId===rec.personId)||(rec.phone&&a.phone===rec.phone)));if(dup)return toast('Người này đã điểm danh trong buổi họp');if(rec.personType==='guest'){let g=S.guests.find(x=>x.phone===rec.phone);if(!g){g={id:uid('G'),fullName:rec.fullName,phone:rec.phone,email:'',address:'',businessType:'',company:rec.company,industry:'',products:'',inviterId:rec.inviterId,status:'attended',createdAt:iso()};S.guests.push(g)}else g.status='attended';rec.personId=g.id}S.attendance.push({id:uid('AT'),meetingId:m.id,...rec,checkedAt:iso()});save();log('Điểm danh','Attendance',`${rec.fullName} • ${m.name}`);q('#checkinSuccess')?.classList.remove('hide');e.target.reset();renderCheckin();toast('Điểm danh thành công','success')};
function renderGuestRegister(){let inv=q('#guestInviter');if(inv)inv.innerHTML='<option value="">Không có</option>'+S.members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}">${esc(m.fullName)}</option>`).join('');toggleCompanyFields()}
window.toggleCompanyFields=()=>{let t=q('#businessType')?.value;qa('[data-company-field]').forEach(x=>x.classList.toggle('hide',t==='Cá nhân'))};
window.submitGuest=e=>{e.preventDefault();let phone=q('#guestRegPhone').value.trim();if(S.guests.some(g=>g.phone===phone))return toast('Số điện thoại này đã có trong CRM');let g={id:uid('G'),fullName:normalizeName(q('#guestRegName').value),phone,email:q('#guestRegEmail').value.trim(),address:q('#guestRegAddress').value.trim(),businessType:q('#businessType').value,company:q('#guestRegCompany')?.value.trim()||'',industry:q('#guestRegIndustry').value.trim(),products:q('#guestRegProducts').value.trim(),inviterId:q('#guestInviter')?.value||null,status:'new',createdAt:iso()};S.guests.push(g);save();log('Đăng ký khách mời','Guest',g.fullName);q('#guestRegSuccess')?.classList.remove('hide');e.target.reset();renderGuestRegister();toast('Đã gửi thông tin. Ban Khách mời sẽ liên hệ.','success')};
function renderOpportunity(){let giver=q('#giverId');if(giver)giver.innerHTML='<option value="">-- Chọn hội viên --</option>'+S.members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}">${esc(m.fullName)}</option>`).join('');let rows=q('#opportunityRows');if(rows&&!rows.children.length)addOpportunityRow()}
window.addOpportunityRow=()=>{let tb=q('#opportunityRows');if(!tb)return;let tr=document.createElement('tr');tr.innerHTML=`<td><select class="oppReceiver" required><option value="">-- Chọn --</option>${S.members.filter(m=>m.status==='active').map(m=>`<option value="M:${m.id}">${esc(m.fullName)} • Hội viên</option>`).join('')}${S.guests.filter(g=>['attended','contacted'].includes(g.status)).map(g=>`<option value="G:${g.id}">${esc(g.fullName)} • Khách mời</option>`).join('')}</select></td><td><select class="oppType"><option>Referral cấp 1</option><option>Referral cấp 2</option><option>Referral cấp 3</option><option>Referral cấp 4</option><option>Referral cấp 5</option><option>Dance 1-2-1</option><option>Cảm ơn đã nhận cơ hội</option></select></td><td><input class="oppValue" type="number" min="0" step="1000" value="0"></td><td><button type="button" class="btn btn-soft btn-sm" onclick="this.closest('tr').remove()">Xóa</button></td>`;tb.append(tr)};
window.submitOpportunity=e=>{e.preventDefault();let giverId=q('#giverId').value;if(!giverId)return toast('Chọn người trao');let rows=qa('#opportunityRows tr');if(!rows.length)return toast('Cần ít nhất một dòng cơ hội');let m=activeMeeting(),added=0;for(let tr of rows){let rv=q('.oppReceiver',tr)?.value;if(!rv)continue;let [kind,id]=rv.split(':');let obj=kind==='M'?S.members.find(x=>x.id===id):S.guests.find(x=>x.id===id);S.opportunities.push({id:uid('OP'),meetingId:m.id,giverId,receiverType:kind==='M'?'member':'guest',receiverId:id,receiverName:obj?.fullName||'',type:q('.oppType',tr).value,value:Number(q('.oppValue',tr).value||0),status:'open',createdAt:iso()});added++}save();log('Trao cơ hội','Opportunity',`${memberName(giverId)} • ${added} cơ hội`);q('#oppSuccess')?.classList.remove('hide');q('#opportunityRows').innerHTML='';addOpportunityRow();toast(`Đã ghi nhận ${added} cơ hội`,'success')};
function homeForUser(u){if(!u)return 'login.html';if(['admin','president'].includes(u.role))return 'admin.html';let map={secretary_lead:'secretariat',vice_president:'vice',training_lead:'training',guest_lead:'guests',event_lead:'events',development_lead:'development',orientation_lead:'orientation',support_director:'support_director'};if(map[u.role])return 'departments.html?dep='+map[u.role];return 'member-portal.html'}
function roleLabel(r){return ({admin:'Admin',president:'Chủ tịch',vice_president:'Phó chủ tịch',secretary_lead:'Trưởng ban Thư ký',training_lead:'Trưởng ban Đào tạo',guest_lead:'Trưởng ban Khách mời',event_lead:'Trưởng ban Sự kiện & Truyền thông',development_lead:'Trưởng ban Phát triển',orientation_lead:'Trưởng ban Định hướng',support_director:'Giám đốc hỗ trợ',member:'Hội viên'})[r]||r}
window.login=e=>{e.preventDefault();let u0=q('#loginUser').value.trim(),p=q('#loginPass').value;let u=S.users.find(x=>x.active&&(x.username===u0||x.phone===u0)&&x.password===p);if(!u)return toast('Sai tài khoản, mật khẩu hoặc tài khoản đang bị khóa');localStorage.setItem(SESSION,JSON.stringify({userId:u.id,loginAt:iso()}));log('Đăng nhập','Auth',u.username);if(u.forcePasswordChange){showForcePassword(u)}else{let params=new URLSearchParams(location.search);location.href=safeNext(params.get('next'))||homeForUser(u)}};
function showForcePassword(u){openModal('Đổi mật khẩu lần đầu',`<div class="notice warn">Mật khẩu phải tối thiểu 8 ký tự, gồm chữ hoa, chữ thường và số.</div><div class="field" style="margin-top:14px"><label>Mật khẩu mới</label><input id="newPassword" type="password"></div><div class="field" style="margin-top:12px"><label>Nhập lại mật khẩu</label><input id="newPassword2" type="password"></div><button class="btn btn-wine" style="margin-top:14px;width:100%" onclick="completePasswordChange('${u.id}')">Đổi mật khẩu</button>`)}
window.completePasswordChange=id=>{let p=q('#newPassword').value,p2=q('#newPassword2').value;if(p!==p2)return toast('Hai mật khẩu không giống nhau');if(!validPassword(p))return toast('Mật khẩu chưa đạt yêu cầu');let u=S.users.find(x=>x.id===id);u.password=p;u.forcePasswordChange=false;save();queueMail(u.email,'Đổi mật khẩu thành công',`Mật khẩu tài khoản ${u.username} đã được thay đổi thành công.`);log('Đổi mật khẩu','User',u.username);location.href=homeForUser(u)};
function logout(){localStorage.removeItem(SESSION);location.href='login.html'} window.logout=logout;
function renderAdmin(){if(!requireAuth())return;let u=currentUser();if(!['admin','president'].includes(u.role)){location.href='departments.html';return}bindAdminLinks();q('#adminUser')&&(q('#adminUser').textContent=(currentMember()?.fullName||u.username).split(' ').slice(-1)[0].slice(0,2).toUpperCase());let wanted=location.hash.replace('#','')||'dashboard';showAdminSection(wanted);showAlerts();}
function showAlerts(){let u=currentUser();if(!u)return;let m=currentMember();let alerts=[];if(m){let mo=new Date().toISOString().slice(0,7);let day=new Date().getDate();let monthly=S.feePayments.some(f=>f.memberId===m.id&&f.feeType==='monthly'&&f.period===mo&&f.status==='confirmed');if(day>=S.config.fees.monthlyDueStart&&!monthly)alerts.push(day<=S.config.fees.monthlyDueEnd?`Phí quỹ tháng ${mo}: ${money(S.config.fees.monthly)}. Hạn nộp từ ngày 01–10.`:`Phí quỹ tháng ${mo}: ${money(S.config.fees.monthly)} đã quá hạn ngày 10 và chưa được Ban Thư ký xác nhận.`);let due=new Date(m.annualDueDate),days=Math.ceil((due-new Date())/86400000);let paid=S.feePayments.some(f=>f.memberId===m.id&&f.feeType==='annual'&&f.period===m.annualDueDate.slice(0,4)&&f.status==='confirmed');if(days<=S.config.fees.annualAlertDays&&!paid)alerts.push(days>=0?`Phí thường niên ${money(S.config.fees.annual)} sẽ đến hạn ngày ${fmtDate(m.annualDueDate)} (${days} ngày nữa).`:`Phí thường niên ${money(S.config.fees.annual)} đã quá hạn ${Math.abs(days)} ngày và chưa được xác nhận.`)}let ev=S.events.find(e=>e.id==='EV-ANN-2026');if(ev&&['admin','president','event_lead'].includes(u.role)){let d=Math.ceil((new Date(ev.date)-new Date())/86400000);if(d>=0&&d<=90)alerts.push(`${ev.title} ngày ${fmtDate(ev.date)} còn ${d} ngày. Ban Sự kiện & Truyền thông cần cập nhật kế hoạch.`)}if(alerts.length){setTimeout(()=>openModal('Cảnh báo Chapter 11',alerts.map(a=>`<div class="notice warn" style="margin-bottom:10px">${esc(a)}</div>`).join('')),250)}}
window.showAdminSection=sec=>{if(!requireAuth())return;if(sec==='settings'&&!isAdmin()){toast('Cấu hình hệ thống chỉ dành cho Admin cao nhất');sec='dashboard'}qa('.content-section').forEach(s=>s.classList.add('hide'));let target=q('#section-'+sec)||q('#section-dashboard');target?.classList.remove('hide');qa('.side-link[data-section]').forEach(a=>a.classList.toggle('active',a.dataset.section===sec));q('#adminTitle')&&(q('#adminTitle').textContent=({dashboard:'Dashboard điều hành',members:'Quản lý hội viên',guests:'Khách mời & CRM','vbna-people':'Danh mục VBNA',meetings:'Cuộc họp & Điểm danh',opportunities:'Cơ hội & Referral',finance:'Tài chính – Thu chi',fees:'Phí hội viên',documents:'Kho chứng từ',leadership:'Leader Team & các Ban',powerteams:'Power Team & Ngành nghề',reports:'Báo cáo nhiệm kỳ',approvals:'Phê duyệt & Nhật ký',settings:'Cấu hình hệ thống'})[sec]||'Dashboard');history.replaceState(null,'','#'+sec);renderAdminSection(sec)};
function renderAdminSection(sec){({dashboard:renderDashboard,members:renderMembers,guests:renderGuests,'vbna-people':renderVbnaPeople,meetings:renderMeetings,opportunities:renderOpportunityDashboard,finance:renderFinance,fees:renderFees,documents:renderDocuments,leadership:renderLeadership,powerteams:renderPowerTeamsAdmin,reports:renderReports,approvals:renderApprovals,settings:renderSettings})[sec]?.()}
function renderDashboard(){let m=activeMeeting(),active=S.members.filter(x=>x.status==='active'),at=S.attendance.filter(x=>x.meetingId===m.id),ops=S.opportunities,fin=S.finance.filter(x=>x.status==='approved'),bal=fin.reduce((a,x)=>a+(x.kind==='income'?x.amount:-x.amount),0);q('#kpiMembers').textContent=active.length;q('#kpiAttendance').textContent=(active.length?Math.round(at.filter(x=>x.personType==='member').length/active.length*100):0)+'%';q('#kpiOpps').textContent=ops.length;q('#kpiOppValue').textContent=money(ops.reduce((a,b)=>a+b.value,0));q('#kpiFund').textContent=money(bal);q('#kpiGuests').textContent=S.guests.length;let al=[];let pending=S.approvals.filter(a=>a.status==='pending').length;if(pending)al.push(`<div class="notice warn">${pending} yêu cầu đang chờ phê duyệt.</div>`);let noDocs=S.finance.filter(f=>f.kind==='expense'&&f.status!=='cancelled'&&!(f.files||[]).length).length;if(noDocs)al.push(`<div class="notice danger">${noDocs} khoản chi chưa có chứng từ.</div>`);q('#dashboardAlerts').innerHTML=al.join('')||'<div class="notice success">Không có cảnh báo vận hành quan trọng.</div>';let rank=rankPeople('giver');q('#topOpportunity').innerHTML=rank.slice(0,5).map((r,i)=>`<div class="metric-row"><span>${i+1}. ${esc(r.name)}</span><b>${r.count} phiếu • ${money(r.value)}</b></div>`).join('');let stages=['new','contacted','attended','interested','application','approved'];q('#guestFunnel').innerHTML=stages.map(st=>`<div class="metric-row"><span>${({new:'Mới đăng ký',contacted:'Đã liên hệ',attended:'Đã tham dự',interested:'Quan tâm hội viên',application:'Đang làm hồ sơ',approved:'Đã kết nạp'})[st]}</span><b>${S.guests.filter(g=>g.status===st).length}</b></div>`).join('')}
function renderMembers(){let term=(q('#memberSearch')?.value||'').toLowerCase(),st=q('#memberStatusFilter')?.value||'';let list=S.members.filter(m=>(!st||m.status===st)&&(!term||[m.fullName,m.phone,m.company,m.industry,m.id].join(' ').toLowerCase().includes(term)));q('#membersTable').innerHTML=list.map(m=>`<tr><td><b>${esc(m.fullName)}</b><br><small>${esc(m.id)} • ${esc(m.phone)}</small></td><td>${esc(m.company)}<br><small>${esc(m.industry)}</small></td><td>${esc(powerName(m.powerTeamId))}</td><td>${fmtDate(m.admitDate)}</td><td>${statusChip(m.status)}</td><td><button class="btn btn-soft btn-sm" onclick="viewMember('${m.id}')">Chi tiết</button> <button class="btn btn-outline btn-sm" onclick="editMember('${m.id}')">Sửa</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Không có dữ liệu</td></tr>'}
window.renderMembers=renderMembers;
window.viewMember=id=>{let m=S.members.find(x=>x.id===id);if(!m)return;let u=S.users.find(x=>x.memberId===id);openModal('Hồ sơ hội viên',`<div class="detail-list"><div class="detail-item"><small>Họ tên</small><strong>${esc(m.fullName)}</strong></div><div class="detail-item"><small>SĐT / Email</small><strong>${esc(m.phone)} • ${esc(m.email)}</strong></div><div class="detail-item"><small>Địa chỉ nhà riêng</small><strong>${esc(m.homeAddress)}</strong></div><div class="detail-item"><small>Doanh nghiệp</small><strong>${esc(m.company)}</strong></div><div class="detail-item"><small>Địa chỉ kinh doanh</small><strong>${esc(m.businessAddress)}</strong></div><div class="detail-item"><small>Ngành nghề</small><strong>${esc(m.industry)}</strong></div><div class="detail-item"><small>Power Team</small><strong>${esc(powerName(m.powerTeamId))}</strong></div><div class="detail-item"><small>Ngày gia nhập / kết nạp</small><strong>${fmtDate(m.joinDate)} / ${fmtDate(m.admitDate)}</strong></div><div class="detail-item"><small>Trạng thái tài khoản</small><strong>${u?.active?'Đang mở':'Chưa có / đã khóa'}</strong></div><div class="detail-item"><small>Tài liệu</small><strong>${(m.documents||[]).length} file</strong></div><div class="detail-item"><small>Ngày dừng / Lý do</small><strong>${fmtDate(m.stopDate)} • ${esc(m.stopReason||'—')}</strong></div></div><div class="toolbar" style="margin-top:16px;flex-wrap:wrap"><button class="btn btn-outline" onclick="requestMemberStatus('${id}','paused')">Tạm dừng</button><button class="btn btn-outline" onclick="requestMemberStatus('${id}','left')">Rời Chapter</button><button class="btn btn-danger" onclick="requestMemberStatus('${id}','terminated')">Chấm dứt tư cách</button>${m.status!=='active'?`<button class="btn btn-soft" onclick="applyMemberStatus('${id}','active')">Khôi phục hội viên</button>`:''}${u?`<button class="btn btn-soft" onclick="toggleMemberAccount('${id}')">${u.active?'Khóa tài khoản':'Mở tài khoản'}</button><button class="btn btn-soft" onclick="resetMemberPassword('${id}')">Reset mật khẩu</button>`:''}</div>`)};
window.editMember=id=>memberForm(S.members.find(x=>x.id===id));window.addMember=()=>memberForm(null);
function memberForm(m){let isNew=!m;openModal(isNew?'Thêm hồ sơ hội viên':'Cập nhật hội viên',`<form id="memberForm" onsubmit="saveMember(event,'${m?.id||''}')"><div class="form-grid"><div class="field"><label>Họ tên *</label><input id="mfName" required value="${esc(m?.fullName||'')}"></div><div class="field"><label>Số điện thoại *</label><input id="mfPhone" required value="${esc(m?.phone||'')}"></div><div class="field"><label>Email *</label><input id="mfEmail" type="email" required value="${esc(m?.email||'')}"></div><div class="field"><label>Ngày sinh</label><input id="mfDob" type="date" value="${esc(m?.dob||'')}"></div><div class="field"><label>Địa chỉ nhà riêng</label><input id="mfHome" value="${esc(m?.homeAddress||'')}"></div><div class="field"><label>Tên doanh nghiệp/HKD</label><input id="mfCompany" value="${esc(m?.company||'')}"></div><div class="field"><label>Chức vụ</label><input id="mfTitle" value="${esc(m?.title||'')}"></div><div class="field"><label>Địa chỉ kinh doanh</label><input id="mfBusinessAddress" value="${esc(m?.businessAddress||'')}"></div><div class="field"><label>Ngành nghề</label><input id="mfIndustry" value="${esc(m?.industry||'')}"></div><div class="field"><label>Sản phẩm/Dịch vụ</label><input id="mfProducts" value="${esc(m?.products||'')}"></div><div class="field"><label>Power Team</label><select id="mfPower">${S.powerTeams.map(p=>`<option value="${p.id}" ${m?.powerTeamId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Ngày gia nhập</label><input id="mfJoin" type="date" value="${esc(m?.joinDate||new Date().toISOString().slice(0,10))}"></div><div class="field"><label>Ngày kết nạp</label><input id="mfAdmit" type="date" value="${esc(m?.admitDate||'')}"></div><div class="field"><label>Hạn phí thường niên</label><input id="mfAnnualDue" type="date" value="${esc(m?.annualDueDate||'')}"></div></div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Ảnh GPLKD</label><input id="mfLicense" type="file" accept="image/*,.pdf"></div><div class="field"><label>Ảnh CCCD</label><input id="mfIdCard" type="file" accept="image/*,.pdf"></div><div class="field"><label>Ảnh mặt tiền cửa hàng/doanh nghiệp</label><input id="mfFront" type="file" accept="image/*"></div><div class="field"><label>File khác (tối đa 10)</label><input id="mfOther" type="file" multiple></div></div><div class="notice" style="margin-top:12px">CCCD và giấy phép kinh doanh là dữ liệu nhạy cảm: chỉ Admin, Chủ tịch và người được phân quyền hồ sơ mới được xem.</div><button class="btn btn-wine" style="margin-top:16px">${isNew?'Tạo hồ sơ & gửi duyệt':'Lưu thay đổi'}</button></form>`)}
window.saveMember=async(e,id)=>{e.preventDefault();let existing=id&&S.members.find(x=>x.id===id);let docs=[...(await persistInputFiles(q('#mfLicense'),1,'license')),...(await persistInputFiles(q('#mfIdCard'),1,'idcard')),...(await persistInputFiles(q('#mfFront'),1,'front')),...(await persistInputFiles(q('#mfOther'),10,'other'))];let obj={id:existing?.id||`C11-${String(S.members.length+1).padStart(4,'0')}`,fullName:normalizeName(q('#mfName').value),phone:q('#mfPhone').value.trim(),email:q('#mfEmail').value.trim(),dob:q('#mfDob').value,homeAddress:q('#mfHome').value.trim(),company:q('#mfCompany').value.trim(),title:q('#mfTitle').value.trim(),businessAddress:q('#mfBusinessAddress').value.trim(),industry:q('#mfIndustry').value.trim(),products:q('#mfProducts').value.trim(),powerTeamId:q('#mfPower').value,joinDate:q('#mfJoin').value,admitDate:q('#mfAdmit').value,annualDueDate:q('#mfAnnualDue').value,stopDate:existing?.stopDate||'',stopReason:existing?.stopReason||'',status:existing?.status||'pending',departmentIds:existing?.departmentIds||[],documents:[...(existing?.documents||[]),...docs]};if(existing)Object.assign(existing,obj);else{S.members.push(obj);S.approvals.unshift({id:uid('APR'),type:'member_admission',entityId:obj.id,title:`Kết nạp ${obj.fullName}`,status:'pending',requestedBy:currentUser()?.id||'PUBLIC',createdAt:iso()})}save();log(existing?'Cập nhật hội viên':'Tạo hồ sơ hội viên','Member',obj.fullName);closeModal();renderMembers();toast(existing?'Đã lưu hồ sơ':'Đã tạo hồ sơ và gửi chờ duyệt','success')};
window.requestMemberStatus=(id,status)=>{let m=S.members.find(x=>x.id===id);openModal('Thay đổi trạng thái hội viên',`<div class="notice warn">Nghiệp vụ này được lưu lịch sử và có thể làm khóa tài khoản đăng nhập.</div><div class="field" style="margin-top:14px"><label>Trạng thái</label><select id="msStatus"><option value="paused" ${status==='paused'?'selected':''}>Tạm dừng</option><option value="left" ${status==='left'?'selected':''}>Rời Chapter</option><option value="terminated" ${status==='terminated'?'selected':''}>Chấm dứt tư cách</option></select></div><div class="field" style="margin-top:12px"><label>Lý do *</label><textarea id="msReason" required></textarea></div><div class="field" style="margin-top:12px"><label>Quyết định / Văn bản đính kèm</label><input id="msDecision" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"></div><button class="btn btn-wine" style="margin-top:14px;width:100%" onclick="submitMemberStatusChange('${id}')">Xác nhận</button>`)};
window.submitMemberStatusChange=async id=>{let status=q('#msStatus').value,reason=q('#msReason').value.trim();if(!reason)return toast('Vui lòng nhập lý do');let docs=await persistInputFiles(q('#msDecision'),1,'decision');if(!['admin','president'].includes(currentUser()?.role)){S.approvals.unshift({id:uid('APR'),type:'member_status',entityId:id,targetStatus:status,title:`Đổi trạng thái ${memberName(id)} → ${status}`,payload:{reason,documents:docs},status:'pending',requestedBy:currentUser()?.id,createdAt:iso()});save();closeModal();toast('Đã gửi yêu cầu phê duyệt');return}applyMemberStatus(id,status,reason,docs)};
window.applyMemberStatus=(id,status,reason='',docs=[])=>applyMemberStatus(id,status,reason,docs);
function applyMemberStatus(id,status,reason='',docs=[]){let m=S.members.find(x=>x.id===id);if(!m)return;m.status=status;if(status==='active'){m.stopDate='';m.stopReason='';let u=S.users.find(x=>x.memberId===id);if(u)u.active=true}else{m.stopDate=new Date().toISOString().slice(0,10);m.stopReason=reason||m.stopReason||'Theo quyết định';m.documents=[...(m.documents||[]),...(docs||[])];let u=S.users.find(x=>x.memberId===id);if(u)u.active=false}save();log('Đổi trạng thái hội viên','Member',`${m.fullName} → ${status}`);renderMembers();closeModal();toast('Đã cập nhật trạng thái','success')}
window.toggleMemberAccount=id=>{if(!['admin','president'].includes(currentUser()?.role))return toast('Chỉ Admin/Chủ tịch được khóa hoặc mở tài khoản');let u=S.users.find(x=>x.memberId===id);if(!u)return toast('Hội viên chưa có tài khoản');u.active=!u.active;save();log(u.active?'Mở tài khoản':'Khóa tài khoản','User',u.username);closeModal();toast(`Tài khoản đã ${u.active?'mở':'khóa'}`,'success')};
window.resetMemberPassword=id=>{if(!['admin','president'].includes(currentUser()?.role))return toast('Chỉ Admin/Chủ tịch được reset mật khẩu');let m=S.members.find(x=>x.id===id),u=S.users.find(x=>x.memberId===id);if(!u)return toast('Hội viên chưa có tài khoản');let p=generatePassword();u.password=p;u.forcePasswordChange=true;u.active=true;queueMail(u.email,'Mật khẩu mới VBNA Chapter 11',`Tài khoản: ${u.username}\nMật khẩu tạm: ${p}\nĐăng nhập tại https://${S.config.domain}/login`);save();log('Reset mật khẩu','User',u.username);openModal('Đã reset mật khẩu',`<div class="notice success">Email mô phỏng đã xếp hàng gửi tới ${esc(u.email)}.</div><div class="detail-item" style="margin-top:12px"><small>Mật khẩu tạm trong prototype</small><strong>${esc(p)}</strong></div>`)};
function activateMemberAccount(id){let m=S.members.find(x=>x.id===id);if(!m)return;let u=S.users.find(x=>x.memberId===id);if(!u){let p=generatePassword();u={id:uid('U'),username:m.phone,phone:m.phone,email:m.email,password:p,role:'member',memberId:m.id,active:true,forcePasswordChange:true};S.users.push(u);queueMail(m.email,'Chào mừng hội viên VBNA Chapter 11',`Xin chào ${m.fullName},\n\nChúc mừng anh/chị đã chính thức được phê duyệt trở thành hội viên VBNA Chapter 11. Với lĩnh vực ${m.industry||'kinh doanh'} tại ${m.company||'doanh nghiệp của anh/chị'}, Chapter 11 kỳ vọng anh/chị sẽ có thêm nhiều kết nối giá trị, cơ hội hợp tác và đóng góp tích cực cho cộng đồng doanh nhân.\n\nLink đăng nhập: https://${S.config.domain}/login\nTài khoản: ${m.phone}\nMật khẩu tạm: ${p}\nVui lòng đổi mật khẩu ngay lần đăng nhập đầu tiên.`)}else u.active=true;m.status='active';if(!m.admitDate)m.admitDate=new Date().toISOString().slice(0,10);save()}
function renderGuests(){q('#guestsTable').innerHTML=S.guests.map(g=>`<tr><td><b>${esc(g.fullName)}</b><br><small>${esc(g.phone)} • ${esc(g.email)}</small></td><td>${esc(g.company||'—')}<br><small>${esc(g.industry||'—')}</small></td><td>${memberName(g.inviterId)}</td><td>${statusChip(g.status)}</td><td><select onchange="updateGuestStatus('${g.id}',this.value)">${['new','contacted','attended','interested','application','approved'].map(s=>`<option ${g.status===s?'selected':''} value="${s}">${s}</option>`).join('')}</select></td></tr>`).join('')}
window.updateGuestStatus=(id,status)=>{let g=S.guests.find(x=>x.id===id);g.status=status;save();log('Cập nhật CRM','Guest',`${g.fullName} → ${status}`);renderGuests()};
function renderVbnaPeople(){q('#externalPeopleTable').innerHTML=S.vbnaPeople.map(p=>`<tr><td>${esc(p.group)}</td><td><b>${esc(p.fullName)}</b><br><small>${esc(p.phone)} • ${esc(p.email)}</small></td><td>${esc(p.chapter)}</td><td>${esc(p.department||'—')}</td><td>${esc(p.company)}</td></tr>`).join('')}
window.addExternalPerson=()=>openModal('Thêm danh mục VBNA',`<form onsubmit="saveExternalPerson(event)"><div class="form-grid"><div class="field"><label>Nhóm</label><select id="epGroup"><option>HĐSL</option><option>HĐTV</option><option>Chủ tịch Chapter</option><option>LT Chapter</option></select></div><div class="field"><label>Họ tên</label><input id="epName" required></div><div class="field"><label>SĐT</label><input id="epPhone" required></div><div class="field"><label>Email</label><input id="epEmail" type="email"></div><div class="field"><label>Chapter</label><input id="epChapter" placeholder="01–23 hoặc VBNA"></div><div class="field"><label>Ban (nếu là LT)</label><select id="epDep"><option value="">—</option>${S.departments.map(d=>`<option>${esc(d.name)}</option>`).join('')}</select></div><div class="field"><label>Doanh nghiệp</label><input id="epCompany"></div><div class="field"><label>Ngành nghề</label><input id="epIndustry"></div></div><button class="btn btn-wine" style="margin-top:14px">Lưu</button></form>`)
window.saveExternalPerson=e=>{e.preventDefault();S.vbnaPeople.push({id:uid('P'),group:q('#epGroup').value,fullName:normalizeName(q('#epName').value),phone:q('#epPhone').value,email:q('#epEmail').value,chapter:q('#epChapter').value,department:q('#epDep').value,company:q('#epCompany').value,industry:q('#epIndustry').value});save();closeModal();renderVbnaPeople();toast('Đã thêm danh mục VBNA','success')};
function renderMeetings(){q('#meetingsTable').innerHTML=S.meetings.map(m=>`<tr><td><b>${esc(m.name)}</b><br><small>${esc(m.publicCode)}</small></td><td>${fmtDate(m.date)} • ${esc(m.time)}</td><td>${esc(m.location)}</td><td>${statusChip(m.status)}</td><td>${S.attendance.filter(a=>a.meetingId===m.id).length}</td></tr>`).join('');let m=activeMeeting();q('#attendanceTable').innerHTML=S.attendance.filter(a=>a.meetingId===m.id).map(a=>`<tr><td>${esc(a.fullName)}</td><td>${esc(a.role)}</td><td>${esc(a.chapter)}</td><td>${maskPhone(a.phone)}</td><td>${memberName(a.inviterId)}</td><td>${fmtDT(a.checkedAt)}</td></tr>`).join('')}
window.addMeeting=()=>openModal('Tạo cuộc họp',`<form onsubmit="saveMeeting(event)"><div class="form-grid"><div class="field"><label>Tên cuộc họp</label><input id="mtName" required></div><div class="field"><label>Ngày</label><input id="mtDate" type="date" required></div><div class="field"><label>Giờ</label><input id="mtTime" type="time" value="13:30"></div><div class="field"><label>Địa điểm</label><input id="mtLocation" value="Hải Phòng"></div><div class="field"><label>Tuần nhiệm kỳ</label><input id="mtWeek" type="number" min="0"></div><div class="field"><label>Trạng thái</label><select id="mtStatus"><option value="scheduled">Đã lên lịch</option><option value="open">Đang mở</option></select></div></div><button class="btn btn-wine" style="margin-top:14px">Tạo cuộc họp</button></form>`)
window.saveMeeting=e=>{e.preventDefault();let status=q('#mtStatus').value;if(status==='open')S.meetings.forEach(x=>x.status=x.status==='open'?'closed':x.status);let m={id:uid('M'),name:q('#mtName').value,date:q('#mtDate').value,time:q('#mtTime').value,location:q('#mtLocation').value,termWeek:Number(q('#mtWeek').value||0),status,publicCode:uid('C11').slice(0,12)};S.meetings.push(m);save();closeModal();renderMeetings();toast('Đã tạo cuộc họp','success')};
function rankPeople(mode='giver'){let map={};for(let o of S.opportunities){let id,name;if(mode==='giver'){id=o.giverId;name=memberName(id)}else{id=o.receiverId;name=o.receiverName}if(!map[id])map[id]={id,name,count:0,value:0,success:0};map[id].count++;map[id].value+=o.value;if(o.status==='success')map[id].success++}return Object.values(map).sort((a,b)=>b.count-a.count||b.value-a.value)}
function renderOpportunityDashboard(){
 let ops=S.opportunities, total=ops.reduce((a,b)=>a+b.value,0),success=ops.filter(o=>o.status==='success'),m=activeMeeting();
 q('#oppTotalCount').textContent=ops.length;q('#oppTotalValue').textContent=money(total);
 q('#opportunitiesTable').innerHTML=ops.slice().reverse().map(o=>`<tr><td>${fmtDT(o.createdAt)}</td><td>${esc(memberName(o.giverId))}</td><td>${esc(o.receiverName)}<br><small>${o.receiverType==='member'?'Hội viên':'Khách mời'}</small></td><td>${esc(o.type)}</td><td class="text-money">${money(o.value)}</td><td>${statusChip(o.status)}</td></tr>`).join('');
 let section=q('#section-opportunities'); let old=q('#oppAdvanced'); if(old)old.remove();
 let today=new Date().toISOString().slice(0,10), month=today.slice(0,7), year=today.slice(0,4), mon=Number(today.slice(5,7)), qStart=Math.floor((mon-1)/3)*3+1;
 let byDate=(pred)=>ops.filter(o=>pred(new Date(o.createdAt)));
 let dToday=byDate(d=>d.toISOString().slice(0,10)===today), dMonth=byDate(d=>d.toISOString().slice(0,7)===month), dQuarter=byDate(d=>d.getFullYear()==year&&d.getMonth()+1>=qStart&&d.getMonth()+1<qStart+3), dYear=byDate(d=>String(d.getFullYear())===year), dMeeting=ops.filter(o=>o.meetingId===m.id);
 let div=document.createElement('div');div.id='oppAdvanced';div.innerHTML=`<div class="kpi-grid" style="margin-top:18px"><div class="kpi"><span>Cơ hội thành công</span><strong>${success.length}</strong><small>${money(success.reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Buổi họp hiện tại</span><strong>${dMeeting.length}</strong><small>${money(dMeeting.reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Tháng hiện tại</span><strong>${dMonth.length}</strong><small>${money(dMonth.reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Năm hiện tại</span><strong>${dYear.length}</strong><small>${money(dYear.reduce((a,b)=>a+b.value,0))}</small></div></div><div class="dashboard-grid"><section class="panel"><h3>Vinh danh người trao cơ hội</h3>${rankPeople('giver').slice(0,10).map((r,i)=>`<div class="metric-row"><span>${i+1}. ${esc(r.name)}</span><b>${r.count} phiếu • ${money(r.value)}</b></div>`).join('')}</section><section class="panel"><h3>Vinh danh người nhận cơ hội</h3>${rankPeople('receiver').slice(0,10).map((r,i)=>`<div class="metric-row"><span>${i+1}. ${esc(r.name)}</span><b>${r.count} phiếu • ${money(r.value)}</b></div>`).join('')}</section></div><section class="panel"><h3>Báo cáo lũy kế theo kỳ</h3><div class="table-wrap"><table class="table"><thead><tr><th>Kỳ</th><th>Số phiếu</th><th>Giá trị</th></tr></thead><tbody><tr><td>Hôm nay</td><td>${dToday.length}</td><td>${money(dToday.reduce((a,b)=>a+b.value,0))}</td></tr><tr><td>Tháng hiện tại</td><td>${dMonth.length}</td><td>${money(dMonth.reduce((a,b)=>a+b.value,0))}</td></tr><tr><td>Quý hiện tại</td><td>${dQuarter.length}</td><td>${money(dQuarter.reduce((a,b)=>a+b.value,0))}</td></tr><tr><td>Năm hiện tại</td><td>${dYear.length}</td><td>${money(dYear.reduce((a,b)=>a+b.value,0))}</td></tr><tr><td>Toàn dữ liệu</td><td>${ops.length}</td><td>${money(total)}</td></tr></tbody></table></div></section>`;section.append(div)
}
function renderFinance(){let inc=S.finance.filter(f=>f.kind==='income'&&f.status==='approved').reduce((a,b)=>a+b.amount,0),exp=S.finance.filter(f=>f.kind==='expense'&&f.status==='approved').reduce((a,b)=>a+b.amount,0),pending=S.finance.filter(f=>f.status==='pending').reduce((a,b)=>a+b.amount,0);q('#finIncome').textContent=money(inc);q('#finExpense').textContent=money(exp);q('#finBalance').textContent=money(inc-exp);q('#finPending').textContent=money(pending);q('#financeTable').innerHTML=S.finance.slice().reverse().map(f=>`<tr><td><b>${esc(f.id)}</b><br><small>${fmtDate(f.date)}</small></td><td>${f.kind==='income'?'Thu':'Chi'} • ${esc(f.costType==='fixed'?'Cố định':'Linh hoạt')}</td><td>${esc(f.category)}<br><small>${esc(f.description)}</small></td><td class="text-money">${money(f.amount)}</td><td>${statusChip(f.status)}</td><td>${(f.files||[]).length} file</td><td>${f.status==='pending'&&['admin','president'].includes(currentUser()?.role)?`<button class="btn btn-soft btn-sm" onclick="approveFinance('${f.id}')">Duyệt</button>`:''}</td></tr>`).join('')}
window.approveFinance=id=>{let f=S.finance.find(x=>x.id===id);f.status='approved';save();log('Duyệt tài chính','Finance',id);renderFinance();toast('Đã duyệt giao dịch','success')};
function renderFees(){let month=new Date().toISOString().slice(0,7);q('#feesTable').innerHTML=S.members.filter(m=>m.status==='active').map(m=>{let mon=S.feePayments.find(f=>f.memberId===m.id&&f.feeType==='monthly'&&f.period===month&&f.status==='confirmed');let yr=S.feePayments.find(f=>f.memberId===m.id&&f.feeType==='annual'&&f.period===m.annualDueDate?.slice(0,4)&&f.status==='confirmed');return `<tr><td><b>${esc(m.fullName)}</b><br><small>${esc(m.phone)}</small></td><td>${mon?statusChip('confirmed'):`<span class="chip red">Chưa nộp ${money(S.config.fees.monthly)}</span>`}</td><td>${yr?statusChip('confirmed'):`<span class="chip gold">Hạn ${fmtDate(m.annualDueDate)}</span>`}</td><td><button class="btn btn-soft btn-sm" onclick="confirmFee('${m.id}','monthly')">Xác nhận phí quỹ</button> <button class="btn btn-outline btn-sm" onclick="confirmFee('${m.id}','annual')">Xác nhận thường niên</button></td></tr>`}).join('')}
window.confirmFee=(id,type)=>{if(!['admin','president','secretary_lead'].includes(currentUser()?.role))return toast('Bạn không có quyền xác nhận phí');let m=S.members.find(x=>x.id===id),period=type==='monthly'?new Date().toISOString().slice(0,7):m.annualDueDate.slice(0,4),amount=type==='monthly'?S.config.fees.monthly:S.config.fees.annual;if(S.feePayments.some(f=>f.memberId===id&&f.feeType===type&&f.period===period&&f.status==='confirmed'))return toast('Khoản phí này đã được xác nhận');let fid=`PT-${new Date().getFullYear()}-${String(S.finance.length+1).padStart(4,'0')}`;S.feePayments.push({id:uid('FP'),memberId:id,feeType:type,period,amount,status:'confirmed',confirmedAt:iso(),financeId:fid});S.finance.push({id:fid,kind:'income',category:type==='monthly'?'Phí sinh hoạt':'Phí thường niên',costType:'fixed',amount,memberId:id,date:new Date().toISOString().slice(0,10),description:`${type==='monthly'?'Phí quỹ':'Phí thường niên'} ${period}`,status:'approved',files:[],createdBy:currentUser()?.id});save();log('Xác nhận phí','Fee',`${m.fullName} • ${type} • ${period}`);renderFees();toast('Đã xác nhận và tự tạo phiếu thu','success')};
function renderDocuments(){let rows=[];for(let m of S.members)for(let d of m.documents||[])rows.push({owner:m.fullName,kind:d.typeGroup||'Hồ sơ',name:d.name,date:m.admitDate,key:d.storageKey});for(let f of S.finance)for(let x of f.files||[])rows.push({owner:f.id,kind:'Chứng từ tài chính',name:typeof x==='string'?x:x.name,date:f.date,key:typeof x==='object'?x.storageKey:null});q('#documentsTable').innerHTML=rows.map(r=>`<tr><td>${esc(r.owner)}</td><td>${esc(r.kind)}</td><td>${esc(r.name)}</td><td>${fmtDate(r.date)}${r.key?`<br><button class="btn btn-soft btn-sm" onclick="downloadStoredFile('${r.key}')">Tải file</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Chưa có file</td></tr>'}
function renderLeadership(){q('#leadershipGrid').innerHTML=S.departments.map(d=>{let ms=S.members.filter(m=>m.departmentIds?.includes(d.id)&&m.status==='active');return `<article class="card"><div class="eyebrow">${esc(d.name)}</div><h3>${esc(ms[0]?.fullName||'Chưa phân công')}</h3><p>${esc(d.scope)}</p><div>${ms.slice(1).map(m=>`<span class="chip gray">${esc(m.fullName)}</span>`).join('')}</div><a class="btn btn-soft btn-sm" style="margin-top:12px" href="departments.html?dep=${d.id}">Mở Dashboard Ban</a></article>`}).join('')}
function renderPowerTeamsAdmin(){q('#powerTeamGrid').innerHTML=S.powerTeams.map(p=>`<article class="card power-card"><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div>${S.members.filter(m=>m.powerTeamId===p.id&&m.status==='active').map(m=>`<span class="chip red">${esc(m.fullName)}</span>`).join('')}</div></article>`).join('')}
function renderReports(){let periods=[{name:'Nhiệm kỳ',from:S.config.term.start,to:S.config.term.end},{name:'Tháng hiện tại',from:new Date().toISOString().slice(0,7)+'-01',to:new Date().toISOString().slice(0,10)}];let ops=S.opportunities,fin=S.finance.filter(f=>f.status==='approved');q('#reportSummary').innerHTML=`<div class="kpi-grid"><div class="kpi"><span>Tổng hội viên</span><strong>${S.members.filter(m=>m.status==='active').length}</strong><small>Hiện tại</small></div><div class="kpi"><span>Tổng khách mời</span><strong>${S.guests.length}</strong><small>CRM</small></div><div class="kpi"><span>Cơ hội thành công</span><strong>${ops.filter(o=>o.status==='success').length}</strong><small>${money(ops.filter(o=>o.status==='success').reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Số dư quỹ</span><strong>${money(fin.reduce((a,b)=>a+(b.kind==='income'?b.amount:-b.amount),0))}</strong><small>Đã duyệt</small></div></div><div class="panel"><h3>Chu kỳ báo cáo</h3>${periods.map(p=>`<div class="metric-row"><span>${p.name}</span><b>${fmtDate(p.from)} → ${fmtDate(p.to)}</b></div>`).join('')}</div>`}
