window.approveRequest=id=>{let a=S.approvals.find(x=>x.id===id);if(!a)return;if(a.type==='member_admission')activateMemberAccount(a.entityId);if(a.type==='member_status')applyMemberStatus(a.entityId,a.targetStatus,a.payload?.reason||'',a.payload?.documents||[]);a.status='approved';a.approvedBy=currentUser().id;a.approvedAt=iso();save();log('Phê duyệt','Approval',a.title);renderApprovals();toast('Đã phê duyệt','success')};
