window.resetDemo=()=>{if(!isAdmin())return toast('Chỉ Admin cao nhất được thao tác');if(!confirm('Khôi phục toàn bộ dữ liệu demo?'))return;S=seed();save();toast('Đã khôi phục dữ liệu demo','success');setTimeout(()=>location.reload(),600)};
function financeAccess(){return ['admin','president','secretary_lead'].includes(currentUser()?.role)}
function renderStandaloneFinance(){if(!requireAuth())return;if(!financeAccess()){location.href='departments.html?dep=secretariat';return}let el=q('#standaloneFinanceTable');if(el)el.innerHTML=S.finance.slice().reverse().map(f=>`<tr><td>${esc(f.id)}</td><td>${f.kind==='income'?'Thu':'Chi'}</td><td>${esc(f.category)}</td><td>${money(f.amount)}</td><td>${statusChip(f.status)}</td></tr>`).join('')}
window.submitFinance=async e=>{e.preventDefault();if(!requireAuth())return;if(!financeAccess())return toast('Bạn không có quyền nhập tài chính');let kind=q('#finKind').value,amount=Number(q('#finAmount').value||0),files=await persistInputFiles(q('#finFiles'),10,'finance');let rec={id:`${kind==='income'?'PT':'PC'}-${new Date().getFullYear()}-${String(S.finance.length+1).padStart(4,'0')}`,kind,category:q('#finCategory').value,costType:q('#finCostType').value,amount,memberId:q('#finMember')?.value||null,date:q('#finDate').value,description:q('#finDescription').value,method:q('#finMethod')?.value||'',files,status:['admin','president'].includes(currentUser()?.role)?'approved':'pending',createdBy:currentUser().id};S.finance.push(rec);save();log('Tạo phiếu tài chính','Finance',rec.id);q('#financeSuccess')?.classList.remove('hide');e.target.reset();initFinanceEntry();toast('Đã lưu phiếu thu/chi','success')};
function initFinanceEntry(){if(!requireAuth())return;if(!financeAccess()){location.href='departments.html?dep=secretariat';return}let sel=q('#finMember');if(sel)sel.innerHTML='<option value="">Không áp dụng</option>'+S.members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}">${esc(m.fullName)}</option>`).join('');let d=q('#finDate');if(d&&!d.value)d.value=new Date().toISOString().slice(0,10)}
function renderDepartments(){if(!requireAuth())return;let params=new URLSearchParams(location.search),depId=params.get('dep')||'president',dep=S.departments.find(d=>d.id===depId)||S.departments[0],u=currentUser(),manage=canManageDepartment(dep.id,u);let menu=q('#departmentMenu');if(menu)menu.innerHTML=S.departments.map(d=>`<a class="side-link ${d.id===dep.id?'active':''}" href="departments.html?dep=${d.id}"><span class="side-icon">◈</span><span>${esc(d.name)}</span></a>`).join('');q('#departmentName')&&(q('#departmentName').textContent=dep.name);q('#departmentScope')&&(q('#departmentScope').textContent=dep.scope);let members=S.members.filter(m=>m.departmentIds?.includes(dep.id)&&m.status==='active'),m=activeMeeting(),at=S.attendance.filter(a=>a.meetingId===m.id),ops=S.opportunities,content=`<div class="kpi-grid"><div class="kpi"><span>Thành viên Ban</span><strong>${members.length}</strong><small>${manage?'Có quyền quản trị':'Chế độ xem'}</small></div><div class="kpi"><span>Điểm danh buổi hiện tại</span><strong>${at.length}</strong><small>${esc(m.name)}</small></div><div class="kpi"><span>Cơ hội nhiệm kỳ</span><strong>${ops.length}</strong><small>${money(ops.reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Việc cần xử lý</span><strong>${S.approvals.filter(a=>a.status==='pending').length}</strong><small>Yêu cầu chờ duyệt</small></div></div><div class="dashboard-grid"><section class="panel"><h3>Nhân sự ${esc(dep.name)}</h3>${members.map(x=>`<div class="metric-row"><span>${esc(x.fullName)}</span><b>${esc(x.company)}</b></div>`).join('')||'<div class="empty">Chưa phân công nhân sự</div>'}</section><section class="panel"><h3>Quyền truy cập</h3><div class="notice ${manage?'success':'warn'}">${manage?'Bạn có quyền xem dữ liệu chi tiết và thao tác của Ban này.':'Bạn là hội viên Chapter 11 nên được xem Dashboard công khai; dữ liệu chi tiết chỉ hiện cho Trưởng ban, thành viên được phân quyền, Chủ tịch và Admin.'}</div></section></div>`;
 if(dep.id==='secretariat')content+=`<section class="panel"><div class="toolbar"><h3>Tài chính – Thu chi – Sổ quỹ</h3><a class="btn btn-wine btn-sm" href="finance.html">Mở tài chính</a></div><div class="metric-list">${S.finance.slice(-6).reverse().map(f=>`<div class="metric-row"><span>${esc(f.id)} • ${esc(f.description)}</span><b>${money(f.amount)}</b></div>`).join('')}</div></section>`;
 if(dep.id==='development')content+=`<section class="panel"><h3>Power Team</h3><div class="grid-3">${S.powerTeams.map(p=>`<article class="card"><b>${esc(p.name)}</b><p>${S.members.filter(x=>x.powerTeamId===p.id&&x.status==='active').length} hội viên</p></article>`).join('')}</div></section>`;
 if(dep.id==='events')content+=`<section class="panel"><h3>Sự kiện trọng điểm</h3>${S.events.filter(e=>e.departmentId==='events').map(e=>`<div class="notice warn"><b>${esc(e.title)}</b><br>${fmtDate(e.date)} • ${esc(e.description)}</div>`).join('')}</section>`;
 if(dep.id==='guests')content+=`<section class="panel"><h3>CRM khách mời</h3>${S.guests.map(g=>`<div class="metric-row"><span>${esc(g.fullName)} • ${esc(g.industry)}</span><b>${esc(g.status)}</b></div>`).join('')}</section>`;
 q('#departmentDashboard')&&(q('#departmentDashboard').innerHTML=content)}
function renderSupport(){if(!requireAuth())return;let el=q('#supportTickets');if(el)el.innerHTML=S.supportTickets.filter(t=>isAdmin()||t.createdBy===currentUser().id).map(t=>`<div class="card"><div class="toolbar"><b>${esc(t.subject)}</b>${statusChip(t.status)}</div><p>${esc(t.message)}</p><small>${fmtDT(t.createdAt)}</small></div>`).join('')||'<div class="empty">Chưa có yêu cầu hỗ trợ</div>'}
window.submitSupport=e=>{e.preventDefault();S.supportTickets.unshift({id:uid('SUP'),subject:q('#supportSubject').value,message:q('#supportMessage').value,priority:q('#supportPriority').value,status:'open',createdBy:currentUser().id,createdAt:iso()});save();log('Tạo yêu cầu hỗ trợ','Support',q('#supportSubject').value);e.target.reset();renderSupport();toast('Đã gửi yêu cầu hỗ trợ','success')};
function renderMemberPortal(){if(!requireAuth())return;let u=currentUser(),m=currentMember();if(!m){q('#memberPortal')&&(q('#memberPortal').innerHTML='<div class="notice warn">Tài khoản này chưa liên kết hồ sơ hội viên.</div>');return}let att=S.attendance.filter(a=>a.personId===m.id),given=S.opportunities.filter(o=>o.giverId===m.id),received=S.opportunities.filter(o=>o.receiverId===m.id),month=new Date().toISOString().slice(0,7),monthly=S.feePayments.some(f=>f.memberId===m.id&&f.feeType==='monthly'&&f.period===month&&f.status==='confirmed');let annual=S.feePayments.some(f=>f.memberId===m.id&&f.feeType==='annual'&&f.period===m.annualDueDate?.slice(0,4)&&f.status==='confirmed');q('#portalMemberName')&&(q('#portalMemberName').textContent=m.fullName);q('#memberPortal')&&(q('#memberPortal').innerHTML=`<div class="kpi-grid"><div class="kpi"><span>Điểm danh</span><strong>${att.length}</strong><small>Lịch sử trong dữ liệu</small></div><div class="kpi"><span>Đã trao cơ hội</span><strong>${given.length}</strong><small>${money(given.reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Được nhận cơ hội</span><strong>${received.length}</strong><small>${money(received.reduce((a,b)=>a+b.value,0))}</small></div><div class="kpi"><span>Power Team</span><strong style="font-size:18px">${esc(powerName(m.powerTeamId))}</strong><small>${esc(m.industry)}</small></div></div><div class="dashboard-grid"><section class="panel"><h3>Hồ sơ của tôi</h3><div class="detail-list"><div class="detail-item"><small>Họ tên</small><strong>${esc(m.fullName)}</strong></div><div class="detail-item"><small>SĐT / Email</small><strong>${esc(m.phone)} • ${esc(m.email)}</strong></div><div class="detail-item"><small>Doanh nghiệp</small><strong>${esc(m.company)}</strong></div><div class="detail-item"><small>Ngành nghề</small><strong>${esc(m.industry)}</strong></div><div class="detail-item"><small>Ngày kết nạp</small><strong>${fmtDate(m.admitDate)}</strong></div><div class="detail-item"><small>Hạn thường niên</small><strong>${fmtDate(m.annualDueDate)}</strong></div></div></section><section class="panel"><h3>Trạng thái phí</h3><div class="metric-row"><span>Phí quỹ tháng ${month}</span><b>${monthly?'Đã xác nhận':'Chưa xác nhận'}</b></div><div class="metric-row"><span>Phí thường niên ${money(S.config.fees.annual)}</span><b>${annual?'Đã xác nhận':'Hạn '+fmtDate(m.annualDueDate)}</b></div><div class="notice ${monthly?'success':'warn'}" style="margin-top:12px">Khi Ban Thư ký xác nhận đã nộp, cảnh báo phí tương ứng sẽ tự tắt.</div></section></div><section class="panel"><div class="toolbar"><h3>Dashboard các Ban</h3><a class="btn btn-outline btn-sm" href="departments.html">Xem toàn bộ</a></div><div class="grid-3">${S.departments.map(d=>`<a class="card" href="departments.html?dep=${d.id}"><div class="eyebrow">${esc(d.name)}</div><b>${esc(d.scope)}</b></a>`).join('')}</div></section>`);showAlerts()}
/* Lucky Draw */
let luckyTimer=null,luckyAudioCtx=null,luckyMusic=false,luckyBeat=null;
function eligibleLucky(){let m=activeMeeting(),seen=new Set(),removed=new Set(S.lucky.removedIds||[]),winners=new Set((S.lucky.winners||[]).filter(w=>w.meetingId===m.id).map(w=>w.personKey));return S.attendance.filter(a=>a.meetingId===m.id).filter(a=>{let key=a.personId||a.phone;if(!key||seen.has(key)||removed.has(key)||winners.has(key))return false;seen.add(key);return true}).map(a=>({...a,personKey:a.personId||a.phone}))}
function renderLucky(){if(!requireAuth())return;let list=eligibleLucky();q('#drawPeopleCount')&&(q('#drawPeopleCount').textContent=list.length);q('#drawPeople')&&(q('#drawPeople').innerHTML=list.map(p=>`<div class="person-row"><strong>${esc(p.fullName)}</strong><small>${esc(p.role)} • ${esc(p.chapter)} • ${maskPhone(p.phone)}</small></div>`).join('')||'<div class="empty" style="color:#fff">Không còn người hợp lệ</div>');let wins=(S.lucky.winners||[]).filter(w=>w.meetingId===activeMeeting().id);q('#winnerList')&&(q('#winnerList').innerHTML=wins.map((w,i)=>`<div class="winner-row"><div class="row"><div><strong>${i+1}. ${esc(w.fullName)}</strong><small>${esc(w.role)} • ${esc(w.chapter)} • ${maskPhone(w.phone)} • ${esc(w.company||'')}</small></div><button class="btn btn-outline btn-sm" onclick="removeLuckyWinner('${w.personKey}')">Loại khỏi phiên</button></div></div>`).join('')||'<div class="empty" style="color:#fff">Chưa có người trúng</div>');qa('.mode-card').forEach(c=>c.onclick=()=>{qa('.mode-card').forEach(x=>x.classList.remove('active'));c.classList.add('active');q('#drawMode').value=c.dataset.mode;q('#winnerCount').disabled=c.dataset.mode==='single';if(c.dataset.mode==='single')q('#winnerCount').value=1});bindLuckyFiles();setTimeout(startDefaultLuckyMusic,300)}
function bindLuckyFiles(){let bg=q('#bgFile'),v=q('#vbnaLogo'),c=q('#c11Logo');if(bg&&!bg.dataset.bound){bg.dataset.bound=1;bg.onchange=e=>previewFileBg(e.target.files[0])}if(v&&!v.dataset.bound){v.dataset.bound=1;v.onchange=e=>previewImg(e.target.files[0],'#vbnaLogoPreview')}if(c&&!c.dataset.bound){c.dataset.bound=1;c.onchange=e=>previewImg(e.target.files[0],'#c11LogoPreview')}}
function previewFileBg(f){if(!f)return;let r=new FileReader();r.onload=()=>{q('.lucky').style.backgroundImage=`linear-gradient(rgba(50,0,8,.68),rgba(90,0,20,.72)),url('${r.result}')`;q('.lucky').style.backgroundSize='cover';q('.lucky').style.backgroundPosition='center'};r.readAsDataURL(f)}
function previewImg(f,sel){if(!f)return;let r=new FileReader();r.onload=()=>{let im=q(sel);im.src=r.result;im.classList.remove('hide')};r.readAsDataURL(f)}
function synthBeat(){try{if(!luckyAudioCtx)luckyAudioCtx=new (window.AudioContext||window.webkitAudioContext)();if(luckyAudioCtx.state==='suspended')luckyAudioCtx.resume().catch(()=>{});let t=luckyAudioCtx.currentTime;[0,0.18,0.36,0.54].forEach((off,i)=>{let o=luckyAudioCtx.createOscillator(),g=luckyAudioCtx.createGain();o.type=i%2?'square':'triangle';o.frequency.value=[523,659,784,659][i];g.gain.setValueAtTime(.0001,t+off);g.gain.exponentialRampToValueAtTime(.035,t+off+.01);g.gain.exponentialRampToValueAtTime(.0001,t+off+.12);o.connect(g).connect(luckyAudioCtx.destination);o.start(t+off);o.stop(t+off+.14)})}catch{}}
function startDefaultLuckyMusic(){if(luckyMusic)return;luckyMusic=true;synthBeat();luckyBeat=setInterval(synthBeat,760)}
function stopDefaultLuckyMusic(){luckyMusic=false;if(luckyBeat){clearInterval(luckyBeat);luckyBeat=null}}
window.toggleLuckyMusic=()=>{let a=q('#customLotteryAudio');if(a?.src){if(a.paused){a.play().catch(()=>toast('Trình duyệt chặn tự phát âm thanh; hãy bấm nút thêm một lần.'));stopDefaultLuckyMusic()}else a.pause();return}luckyMusic?stopDefaultLuckyMusic():startDefaultLuckyMusic()};
window.loadLuckyMusic=e=>{let f=e.target.files[0];if(!f)return;let a=q('#customLotteryAudio');a.src=URL.createObjectURL(f);a.loop=true;stopDefaultLuckyMusic();a.play().catch(()=>toast('Đã nạp nhạc. Bấm Phát/Tạm dừng nhạc để kích hoạt.'))};
window.shuffleLucky=()=>{S.lucky.shuffleSeed=(S.lucky.shuffleSeed||0)+1;save();let list=eligibleLucky().sort(()=>Math.random()-.5);q('#drawPeople').innerHTML=list.map(p=>`<div class="person-row"><strong>${esc(p.fullName)}</strong><small>${esc(p.role)} • ${maskPhone(p.phone)}</small></div>`).join('');toast('Đã xáo trộn danh sách')};
window.drawLucky=()=>{if(luckyTimer)return;let list=eligibleLucky();let exclude=(q('#excludeText').value||'').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);list=list.filter(p=>!exclude.some(x=>p.fullName.toLowerCase().includes(x)||p.phone.includes(x)));let count=q('#drawMode').value==='single'?1:Math.max(1,Math.min(Number(q('#winnerCount').value||1),50));if(!list.length)return toast('Không còn người đủ điều kiện quay');count=Math.min(count,list.length);let sec=Math.max(1,Number(q('#drawSeconds').value||5)),start=Date.now();startDefaultLuckyMusic();q('.slot').classList.add('celebrate');luckyTimer=setInterval(()=>{let p=list[Math.floor(Math.random()*list.length)];q('#slotName').textContent=p.fullName;q('#slotMeta').textContent=`${p.role} • ${p.chapter} • ${maskPhone(p.phone)}`;if(Date.now()-start>=sec*1000){clearInterval(luckyTimer);luckyTimer=null;let picked=[];let pool=[...list];for(let i=0;i<count;i++){let ix=Math.floor(Math.random()*pool.length);picked.push(pool.splice(ix,1)[0])}for(let p of picked)S.lucky.winners.push({id:uid('WIN'),meetingId:activeMeeting().id,personKey:p.personKey,fullName:p.fullName,phone:p.phone,role:p.role,chapter:p.chapter,company:p.company||'',wonAt:iso()});save();let main=picked[0];q('#slotName').textContent=count===1?main.fullName:`${count} NGƯỜI TRÚNG`;q('#slotMeta').textContent=count===1?`${main.role} • ${main.chapter} • ${maskPhone(main.phone)}`:picked.map(x=>x.fullName).join(' • ');renderLucky();log('Lucky Draw','Winner',picked.map(x=>x.fullName).join(', '));setTimeout(()=>q('.slot')?.classList.remove('celebrate'),1500)}},80)};
window.removeLuckyWinner=key=>{if(!S.lucky.removedIds.includes(key))S.lucky.removedIds.push(key);save();renderLucky();toast('Đã loại người này khỏi các lượt quay tiếp')};
window.resetLucky=()=>{if(!confirm('Làm mới kết quả Lucky Draw của buổi họp hiện tại?'))return;let mid=activeMeeting().id;S.lucky.winners=S.lucky.winners.filter(w=>w.meetingId!==mid);S.lucky.removedIds=[];save();renderLucky();q('#slotName').textContent='Sẵn sàng quay';q('#slotMeta').textContent='Danh sách lấy từ điểm danh, đã khử trùng'};
window.exportReportCsv=()=>{if(!requireAuth())return;let rows=[['LOAI','HO TEN','DOANH NGHIEP','NGANH NGHE','TRANG THAI'],...S.members.map(m=>['HOI VIEN',m.fullName,m.company,m.industry,m.status]),[],['CO HOI','NGUOI TRAO','NGUOI NHAN','LOAI','GIA TRI','TRANG THAI'],...S.opportunities.map(o=>['CO HOI',memberName(o.giverId),o.receiverName,o.type,o.value,o.status]),[],['TAI CHINH','MA PHIEU','DANH MUC','NOI DUNG','SO TIEN','TRANG THAI'],...S.finance.map(f=>['TAI CHINH',f.id,f.category,f.description,(f.kind==='income'?f.amount:-f.amount),f.status])];let csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`VBNA_Chapter11_Report_${new Date().toISOString().slice(0,10)}.csv`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);log('Xuất báo cáo','Report','CSV tổng hợp')};
